PREFIX  dbpr: <http://dbpedia.org/resource/>
PREFIX  dbpo: <http://dbpedia.org/ontology/>

SELECT DISTINCT  ?movie ?date
WHERE
  {   { ?movie  dbpo:director     dbpr:Woody_Allen ;
                dbpo:releaseDate  ?date
      }
    UNION
      { ?movie  dbpo:author       dbpr:Woody_Allen ;
                dbpo:releaseDate  ?date
      }
    UNION
      { ?movie  dbpo:starring     dbpr:Woody_Allen ;
                dbpo:releaseDate  ?date
      }
  }
ORDER BY ?date

