PREFIX  dct:  <http://purl.org/dc/terms/>
PREFIX  planet: <http://dbpedia.org/>

SELECT  ?property ?isValueOf
WHERE
  {   { ?isValueOf  ?property  :Category:Mexican_cuisine }
    UNION
      { ?sub  :  dct:subject }
  }

negative_queries.query:
PREFIX  dbpo: <http://dbpedia.org/ontology/>
PREFIX  rdf:  <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX  gsp:  <http://www.opengis.net/ont/geosparql#>
PREFIX  xsd:  <http://www.w3.org/2001/XMLSchema#>
PREFIX  rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX  foaf: <http://xmlns.com/foaf/0.1/>
PREFIX  dbprop: <http://dbpedia.org/property/>

SELECT  *
WHERE
  {   { ?city  rdfs:label  "Amsterdam"@de }
    UNION
      { ?alias  dbprop:redirect  ?city ;
                rdfs:label       "Amsterdam"@de
      }
    UNION
      { ?alias  dbprop:disambiguates  ?city ;
                rdfs:label            "Amsterdam"@de
      }
    OPTIONAL
      { ?city  dbpo:abstract  ?abstract }
    OPTIONAL
      { ?city  gsp:lat   ?latitude ;
               gsp:long  ?longitude
      }
    OPTIONAL
      { ?city  foaf:depiction  ?image }
    OPTIONAL
      { ?city  rdfs:label  ?name }
    OPTIONAL
      { ?city  foaf:homepage  ?home }
    OPTIONAL
      { ?city  dbpo:populationTotal  ?population }
    OPTIONAL
      { ?city  dbpo:thumbnail  ?thumbnail }
    FILTER langMatches(lang(?abstract), "de")
  }

PREFIX  dbpo: <http://dbpedia.org/ontology/>
